from abc import ABC, abstractmethod


class Pricing(ABC):
    @abstractmethod
    def price(self, base): ...


class StudentPricing(Pricing):
    def price(self, base):
        return base


class StaffPricing(Pricing):
    def price(self, base):
        return round(base * 1.2)


class GuestPricing(Pricing):
    def price(self, base):
        return round(base * 1.5) + 10      # visitor surcharge


class FestivalPricing(Pricing):            # added later: no other class changed
    def __init__(self, inner, off):
        self.inner, self.off = inner, off

    def price(self, base):
        return max(0, self.inner.price(base) - self.off)


class Checkout:
    def __init__(self, pricing: Pricing):
        self.pricing = pricing

    def bill(self, items):
        return sum(self.pricing.price(p) for p in items)


tray = [30, 10, 15]                         # poha, chai, samosa
for name, rule in [("student", StudentPricing()), ("staff", StaffPricing()),
                   ("guest", GuestPricing()), ("student on Diwali", FestivalPricing(StudentPricing(), 5))]:
    print(f"{name:<18} Rs {Checkout(rule).bill(tray)}")
